#include <cstdint>
#include <cstring>
#include <string>
#include <vector>

using NTSTATUS = std::int32_t;
constexpr NTSTATUS STATUS_SUCCESS = 0;
constexpr NTSTATUS STATUS_INVALID_PARAMETER = static_cast<NTSTATUS>(0xC000000Du);
constexpr NTSTATUS STATUS_INVALID_DEVICE_REQUEST = static_cast<NTSTATUS>(0xC0000010u);
constexpr NTSTATUS STATUS_ACCESS_DENIED = static_cast<NTSTATUS>(0xC0000022u);
constexpr NTSTATUS STATUS_BUFFER_TOO_SMALL = static_cast<NTSTATUS>(0xC0000023u);
enum Major { IRP_MJ_CREATE = 0, IRP_MJ_CLOSE = 2, IRP_MJ_READ = 3, IRP_MJ_WRITE = 4, IRP_MJ_DEVICE_CONTROL = 14 };

constexpr std::uint32_t ctl(std::uint32_t fn, std::uint32_t access) { return (0x8000u << 16) | (access << 14) | (fn << 2); }
constexpr std::uint32_t IOCTL_ECHO = ctl(0x800, 0), IOCTL_GET_STATS = ctl(0x801, 1), IOCTL_RESET = ctl(0x802, 2),
                        IOCTL_SET_NAME = ctl(0x803, 2), IOCTL_GET_NAME = ctl(0x804, 1);

struct Irp
{
    int major;
    std::uint32_t code{ 0 };
    std::vector<std::uint8_t> systemBuffer;
    std::uint32_t inLength{ 0 }, outLength{ 0 };
    std::uint32_t handleAccess{ 3 };
    NTSTATUS status{ 0 };
    std::uint64_t information{ 0 };
    int completions{ 0 };
};

class EchoDevice
{
public:
    void dispatch(Irp& irp)
    {
        switch (irp.major)
        {
        case IRP_MJ_CREATE:
        case IRP_MJ_CLOSE: complete(irp, STATUS_SUCCESS, 0); return;
        case IRP_MJ_WRITE: m_bytes += irp.inLength; complete(irp, STATUS_SUCCESS, irp.inLength); return;
        case IRP_MJ_DEVICE_CONTROL: deviceControl(irp); return;
        default: complete(irp, STATUS_INVALID_DEVICE_REQUEST, 0); return;
        }
    }

    std::uint32_t echoes() const { return m_echoes; }
    std::uint64_t bytesWritten() const { return m_bytes; }
    std::u16string name() const { return m_name; }

private:
    static void complete(Irp& irp, NTSTATUS status, std::uint64_t info)
    {
        irp.status = status;
        irp.information = status >= 0 ? info : 0;
        ++irp.completions;
    }

    void deviceControl(Irp& irp)
    {
        const std::uint32_t required{ (irp.code >> 14) & 3u };
        if (required & ~irp.handleAccess) { complete(irp, STATUS_ACCESS_DENIED, 0); return; }
        std::uint8_t* buf{ irp.systemBuffer.data() };

        switch (irp.code)
        {
        case IOCTL_ECHO:
            if (irp.outLength < irp.inLength) { complete(irp, STATUS_BUFFER_TOO_SMALL, 0); return; }
            ++m_echoes;
            complete(irp, STATUS_SUCCESS, irp.inLength);
            return;

        case IOCTL_GET_STATS:
        {
            if (irp.outLength < 16) { complete(irp, STATUS_BUFFER_TOO_SMALL, 0); return; }
            const std::uint32_t size{ 16 };
            std::memcpy(buf, &size, 4);
            std::memcpy(buf + 4, &m_echoes, 4);
            std::memcpy(buf + 8, &m_bytes, 8);
            complete(irp, STATUS_SUCCESS, 16);
            return;
        }

        case IOCTL_RESET:
            m_echoes = 0;
            m_bytes = 0;
            complete(irp, STATUS_SUCCESS, 0);
            return;

        case IOCTL_SET_NAME:
        {
            if (irp.inLength < 8) { complete(irp, STATUS_BUFFER_TOO_SMALL, 0); return; }
            std::uint32_t header[2];
            std::memcpy(header, buf, 8);                                     // copy once
            const std::uint32_t size{ header[0] }, length{ header[1] };
            if (size != 8 || length % 2 || length > 64 || length > irp.inLength - 8) { complete(irp, STATUS_INVALID_PARAMETER, 0); return; }
            m_name.assign(length / 2, u'\0');
            std::memcpy(m_name.data(), buf + 8, length);
            complete(irp, STATUS_SUCCESS, 0);
            return;
        }

        case IOCTL_GET_NAME:
        {
            const std::uint32_t length{ static_cast<std::uint32_t>(m_name.size() * 2) };
            if (irp.outLength < 4 + length) { complete(irp, STATUS_BUFFER_TOO_SMALL, 0); return; }
            std::memcpy(buf, &length, 4);
            if (length) std::memcpy(buf + 4, m_name.data(), length);
            complete(irp, STATUS_SUCCESS, 4 + length);
            return;
        }
        }
        complete(irp, STATUS_INVALID_DEVICE_REQUEST, 0);
    }

    std::uint32_t m_echoes{ 0 };
    std::uint64_t m_bytes{ 0 };
    std::u16string m_name;
};

