#include <algorithm>
#include <cstring>
Irp ioctl(std::uint32_t code, const std::vector<std::uint8_t>& input, std::uint32_t outLength, std::uint32_t access = 3) {
    Irp i{ IRP_MJ_DEVICE_CONTROL }; i.code = code; i.inLength = static_cast<std::uint32_t>(input.size()); i.outLength = outLength; i.handleAccess = access;
    i.systemBuffer.assign(std::max<std::size_t>(input.size(), outLength), 0xCC); std::copy(input.begin(), input.end(), i.systemBuffer.begin()); return i;
}
std::vector<std::uint8_t> nameRequest(std::uint32_t size, std::uint32_t length, const std::u16string& text) {
    std::vector<std::uint8_t> b(8 + text.size() * 2); std::memcpy(b.data(), &size, 4); std::memcpy(b.data() + 4, &length, 4); if (!text.empty()) std::memcpy(b.data() + 8, text.data(), text.size() * 2); return b;
}
TEST("create, close, write, read") {
    EchoDevice d; Irp c{ IRP_MJ_CREATE }; d.dispatch(c); CHECK_EQ(c.status, STATUS_SUCCESS); CHECK_EQ(c.completions, 1);
    Irp w{ IRP_MJ_WRITE }; w.inLength = 300; d.dispatch(w); CHECK_EQ(w.information, 300ull); CHECK_EQ(d.bytesWritten(), 300ull);
    Irp r{ IRP_MJ_READ }; r.outLength = 10; d.dispatch(r); CHECK_EQ(r.status, STATUS_INVALID_DEVICE_REQUEST); CHECK_EQ(r.information, 0ull); CHECK_EQ(r.completions, 1);
}
TEST("echo") {
    EchoDevice d; Irp e = ioctl(IOCTL_ECHO, { 'h', 'i', '!' }, 8); d.dispatch(e);
    CHECK_EQ(e.status, STATUS_SUCCESS); CHECK_EQ(e.information, 3ull); CHECK_EQ(e.systemBuffer[2], std::uint8_t('!')); CHECK_EQ(d.echoes(), 1u);
    Irp small = ioctl(IOCTL_ECHO, { 1, 2, 3, 4 }, 2); d.dispatch(small); CHECK_EQ(small.status, STATUS_BUFFER_TOO_SMALL); CHECK_EQ(small.information, 0ull); CHECK_EQ(d.echoes(), 1u);
}
TEST("statistics and access") {
    EchoDevice d; Irp w{ IRP_MJ_WRITE }; w.inLength = 70000; d.dispatch(w); Irp e = ioctl(IOCTL_ECHO, { 1 }, 1); d.dispatch(e);
    Irp s = ioctl(IOCTL_GET_STATS, {}, 16, 1); d.dispatch(s); CHECK_EQ(s.information, 16ull);
    std::uint32_t size, echoes; std::uint64_t bytes; std::memcpy(&size, s.systemBuffer.data(), 4); std::memcpy(&echoes, s.systemBuffer.data() + 4, 4); std::memcpy(&bytes, s.systemBuffer.data() + 8, 8);
    CHECK_EQ(size, 16u); CHECK_EQ(echoes, 1u); CHECK_EQ(bytes, 70000ull);
    Irp noRead = ioctl(IOCTL_GET_STATS, {}, 16, 2); d.dispatch(noRead); CHECK_EQ(noRead.status, STATUS_ACCESS_DENIED);
    Irp noWrite = ioctl(IOCTL_RESET, {}, 0, 1); d.dispatch(noWrite); CHECK_EQ(noWrite.status, STATUS_ACCESS_DENIED); CHECK_EQ(d.echoes(), 1u);
    Irp reset = ioctl(IOCTL_RESET, {}, 0, 2); d.dispatch(reset); CHECK_EQ(reset.status, STATUS_SUCCESS); CHECK_EQ(d.echoes(), 0u); CHECK_EQ(d.bytesWritten(), 0ull);
    Irp tooSmall = ioctl(IOCTL_GET_STATS, {}, 15); d.dispatch(tooSmall); CHECK_EQ(tooSmall.status, STATUS_BUFFER_TOO_SMALL);
}
TEST("setting and getting the name") {
    EchoDevice d; Irp set = ioctl(IOCTL_SET_NAME, nameRequest(8, 10, u"Xenon"), 0); d.dispatch(set); CHECK_EQ(set.status, STATUS_SUCCESS); CHECK(d.name() == u"Xenon");
    Irp get = ioctl(IOCTL_GET_NAME, {}, 14); d.dispatch(get); CHECK_EQ(get.information, 14ull); std::uint32_t len; std::memcpy(&len, get.systemBuffer.data(), 4); CHECK_EQ(len, 10u);
    Irp shortGet = ioctl(IOCTL_GET_NAME, {}, 13); d.dispatch(shortGet); CHECK_EQ(shortGet.status, STATUS_BUFFER_TOO_SMALL);
}
TEST("hostile names") {
    EchoDevice d; Irp first = ioctl(IOCTL_SET_NAME, nameRequest(8, 4, u"ok"), 0); d.dispatch(first);
    for (const auto& input : { nameRequest(12, 4, u"ab"), nameRequest(8, 3, u"ab"), nameRequest(8, 66, std::u16string(33, u'x')), nameRequest(8, 0xFFFFFFFCu, u"ab"), nameRequest(8, 6, u"ab") }) {
        Irp i = ioctl(IOCTL_SET_NAME, input, 0); d.dispatch(i); CHECK_EQ(i.status, STATUS_INVALID_PARAMETER); CHECK_EQ(i.completions, 1);
    }
    Irp tiny = ioctl(IOCTL_SET_NAME, { 8, 0, 0 }, 0); d.dispatch(tiny); CHECK_EQ(tiny.status, STATUS_BUFFER_TOO_SMALL);
    Irp readOnly = ioctl(IOCTL_SET_NAME, nameRequest(8, 2, u"x"), 0, 1); d.dispatch(readOnly); CHECK_EQ(readOnly.status, STATUS_ACCESS_DENIED);
    CHECK(d.name() == u"ok");
}
TEST("unknown codes") { EchoDevice d; Irp i = ioctl(ctl(0x900, 0), {}, 0); d.dispatch(i); CHECK_EQ(i.status, STATUS_INVALID_DEVICE_REQUEST); Irp m = ioctl(IOCTL_ECHO | 3u, { 1 }, 1); d.dispatch(m); CHECK_EQ(m.status, STATUS_INVALID_DEVICE_REQUEST); }

